mapper.select:
SELECT IDX, TITLE, PRESS, IMG_URL1, URL 
FROM (
    SELECT MIN(IDX) AS IDX, pid, TITLE, PRESS, IMG_URL1, URL, DT
    FROM ANS_BREAKING_NEWS
    GROUP BY pid, TITLE, PRESS, IMG_URL1, URL, DT
    ORDER BY DT DESC
    LIMIT #{pageSize} OFFSET #{offset}
) AS sub
ORDER BY DT DESC;

SELECT IDX, TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_MAIN_NEWS
WHERE idx=#{idx}

SELECT IDX, TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT TEXT
FROM ANS_MAIN_NEWS  
WHERE idx=#{idx}

SELECT TEXT
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT title, MAX(dt) AS dt, MIN(idx) AS idx                                          
FROM (
    SELECT title, dt, idx FROM ANS_MAIN_NEWS
    WHERE title != #{excludeTitle}
    AND title LIKE CONCAT('%', #{hashtag}, '%')

    UNION ALL

    SELECT title, dt, idx FROM ANS_BREAKING_NEWS
    WHERE title != #{excludeTitle}
    AND title LIKE CONCAT('%', #{hashtag}, '%')
) AS combined_news                                          

GROUP BY title                                          
ORDER BY dt DESC
LIMIT #{limit}

