SELECT IDX, TITLE, PRESS, IMG_URL1, URL, VIEW
FROM (
    SELECT MIN(IDX) AS IDX, pid, TITLE, PRESS, IMG_URL1, URL, VIEW, DT
    FROM ANS_BREAKING_NEWS
    GROUP BY pid, TITLE, PRESS, IMG_URL1, URL, VIEW, DT
    ORDER BY VIEW DESC, DT DESC                  
    LIMIT #{pageSize} OFFSET #{offset}
) AS sub
ORDER BY VIEW DESC, DT DESC;

SELECT IDX, TITLE, PRESS, IMG_URL1, URL, VIEW
FROM (
    SELECT MIN(IDX) AS IDX, pid, TITLE, PRESS, IMG_URL1, URL, VIEW, DT
    FROM ANS_MAIN_NEWS
    GROUP BY pid, TITLE, PRESS, IMG_URL1, URL, VIEW, DT
    ORDER BY VIEW DESC, DT DESC                  
    LIMIT #{pageSize} OFFSET #{offset}
) AS sub
ORDER BY VIEW DESC, DT DESC;
